-- Prima infornata dalla nuova fonte fisica "Fiori e Piante da Appartamento"
-- (collana Fiori & Piante, Edicart/Royal Smeets Offset bv, 1995, con la
-- collaborazione della Vaste Keurings Commissie olandese) — 7 nuove specie
-- (#120 espansione catalogo, generi non ancora presenti). Foto scattate da
-- Roberta pagina per pagina, lette direttamente (nessun OCR: l'OCR tentato
-- in precedenza perdeva completamente le icone della legenda).
--
-- Anthurium, incontrato nello stesso libro, è stato saltato: già presente
-- e verificato nel catalogo su fonte RHS.
--
-- Acalypha: il libro mostra il simbolo "pieno sole" ma il testo raccomanda
-- esplicitamente di evitare i raggi diretti — seguito il testo, più
-- specifico e prudente, segnalata la discrepanza nell'alert.
--
-- Anigozanthos: segnalata pianta velenosa (simbolo esplicito nel libro).
--
-- giorni_germinazione/trapianto/raccolta lasciati null per tutte: il libro
-- non fornisce conteggi di giorni precisi, solo temperature e stagioni.
-- famiglia_botanica compilata da tassonomia standard dove il libro non la
-- dichiara esplicitamente (dato oggettivo, non specifico di questa fonte).

insert into specie
  (nome, nome_scientifico, famiglia_botanica, descrizione, esigenze, alert, manutenzione, ciclo_colturale, vaso, ciclo_vitale, slug, fonti, stato_verifica, verificata_il, verificata_da)
values
($t$Acalypha$t$, $t$Acalypha$t$, $t$Euphorbiaceae$t$, $t$Genere originario delle isole dell'arcipelago australiano, diffuso come pianta ornamentale in tutte le regioni tropicali. Infiorescenze a spighe cilindriche ricadenti, rosso-amaranto, lunghe anche 50cm; alcune specie (A. wilkesiana) hanno foglie colorate verde-bronzo, gialle o rosse.$t$, $j${"luce": "Molto luminosa, ma senza sole diretto", "acqua": "Abbondante in primavera-estate con nebulizzazioni, ridotta in inverno", "terreno": "Fresco e ricco: pacciame o torba, sabbia, concime organico e argilla"}$j$::jsonb, ARRAY[$t$il libro riporta il simbolo "pieno sole", ma il testo raccomanda esplicitamente di tenerla lontana dai raggi diretti: seguita l'indicazione testuale, più prudente$t$, $t$se l'umidità ambientale è troppo bassa può essere infestata da acari rossi (ragnetto rosso)$t$, $t$cimare più volte gli apici vegetativi per una pianta più folta$t$, $t$temperatura ideale 16-20°C in vegetazione, 13-18°C a riposo invernale in locale asciutto$t$], $j${"irrigazione": {"primavera": "abbondante, con acqua tiepida", "estate": "abbondante, con acqua tiepida e nebulizzazioni", "autunno": "ridotta", "inverno": "minima, ambiente asciutto"}, "concimazione": {"primavera": "ogni 2 settimane", "estate": "ogni 2 settimane", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "cimare gli apici per infoltire", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Euphorbiaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 5, "rinvaso_ogni_mesi": 18, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$acalypha$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Achimenes$t$, $t$Achimenes$t$, $t$Gesneriaceae$t$, $t$Il nome deriva dal greco a-kheimon, "senza inverno": genere di piante a tuberi squamosi originario dell'America centrale e meridionale, con scarsa tolleranza ai climi invernali. Fiori ad ampia scodella bianchi, rossi, rosa, porpora o gialli, ciascuno dura 2-5 settimane.$t$, $j${"luce": "Mezz'ombra", "acqua": "Regolare, con acqua tiepida (mai fredda, provoca macchie sulle foglie)", "terreno": "Leggermente acido, ricco di humus: pacciame, torba, sabbia e concime organico in parti uguali"}$j$::jsonb, ARRAY[$t$dopo la fioritura (settembre) la pianta appassisce alla base: tagliare i fusti e conservare il cespo a circa 15°C, terriccio asciutto, per gennaio/febbraio$t$, $t$reinterrare il cespo in circa 2cm di terreno fresco sempre umido, a 18-20°C, per farlo ripartire$t$, $t$non esporre a correnti d'aria né a raggi diretti del sole$t$, $t$nebulizzare spesso per evitare l'infestazione da acari rossi$t$, $t$temperatura di crescita ideale 20-30°C$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare-abbondante", "autunno": "ridotta, poi sospesa dopo la fioritura", "inverno": "sospesa (riposo del tubero)"}, "concimazione": {"primavera": "ogni 2 settimane", "estate": "ogni 2 settimane", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "taglio dei fusti dopo l'appassimento", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Gesneriaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 15, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 1, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$achimenes$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Anigozanthos$t$, $t$Anigozanthos$t$, $t$Haemodoraceae$t$, $t$Il nome significa "pianta dal fiore strano": genere originario delle regioni subtropicali dell'Australia, noto come kangaroo paw ("zampa di canguro") per i fiori tomentosi imbutiformi che si ripiegano verso l'alto. Foglie lineari, fusti pelosi rossi o verdi.$t$, $j${"luce": "Pieno sole", "acqua": "Regolare, terreno sempre umido", "terreno": "Ben drenato: parti uguali di torba, sabbia grossa e argilla"}$j$::jsonb, ARRAY[$t$pianta velenosa (simbolo esplicito nel libro): tenere lontana da bambini e animali domestici$t$, $t$richiede molta aria fresca e un vaso grande$t$, $t$recidere i fiori al termine della fioritura e rinvasare$t$, $t$temperatura 16-30°C, in inverno 5-15°C: diradare le annaffiature in inverno$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "ridotta", "inverno": "diradata"}, "concimazione": {"primavera": "ogni 2 settimane", "estate": "ogni 2 settimane", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "recidere i fiori dopo la fioritura", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Haemodoraceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "bassa", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 5, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$anigozanthos$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Aphelandra$t$, $t$Aphelandra$t$, $t$Acanthaceae$t$, $t$Genere nativo delle zone tropicali e subtropicali dell'America, con circa 300 specie a fiori rossi, arancioni e gialli. La specie da appartamento più nota è A. squarrosa, con grandi foglie lucide verde scuro striate di bianco e fiori bilobati riuniti in spighe terminali circondate da brattee.$t$, $j${"luce": "Mezz'ombra: posizione luminosa ma non esposta al sole", "acqua": "Abbondante durante la fioritura, terreno sempre umido", "terreno": "Soffice e sostanzioso: terra specifica per Anthurium o terra per vasi con aggiunta di torba"}$j$::jsonb, ARRAY[$t$il terreno lasciato asciugare favorisce lo sviluppo di afidi$t$, $t$foglie che diventano marroni → temperatura troppo bassa oppure pianta esposta al sole$t$, $t$recidere le infiorescenze dopo la fioritura$t$, $t$può essere cimata o potata; rinvaso in marzo$t$, $t$temperatura 18-25°C, in inverno 10-14°C$t$], $j${"irrigazione": {"primavera": "abbondante", "estate": "abbondante (durante la fioritura)", "autunno": "moderata", "inverno": "ridotta"}, "concimazione": {"primavera": "una volta a settimana", "estate": "una volta a settimana", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "cimatura leggera", "estate": "recidere le infiorescenze dopo la fioritura", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Acanthaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 30, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 2, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$aphelandra$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Ardisia$t$, $t$Ardisia$t$, $t$Primulaceae$t$, $t$Genere proveniente dalle regioni tropicali boschive dell'Asia meridionale e orientale, arbustivo perenne, coltivato per i bei frutti rossi lucenti di lunga durata. I margini spessi delle foglie ospitano il Bacillus follicola, un batterio innocuo per l'uomo che vive in simbiosi con la pianta.$t$, $j${"luce": "Mezz'ombra: posizione arieggiata e luminosa, non esposta direttamente al sole", "acqua": "Regolare, terreno sempre umido", "terreno": "Qualsiasi terreno da vaso, purché sempre umido"}$j$::jsonb, ARRAY[$t$se l'ambiente è più caldo di 22°C i frutti cadono: temperatura ideale 12-16°C in inverno$t$, $t$per favorire la formazione dei frutti, distribuire il polline sui fiori con un pennello$t$, $t$potare a 5cm dal suolo per ottenere uno sviluppo arbustivo compatto$t$, $t$sensibile agli insetticidi in aerosol$t$, $t$non nebulizzare durante il periodo della fioritura$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "regolare", "inverno": "ridotta"}, "concimazione": {"primavera": "ogni 2 settimane", "estate": "ogni 2 settimane", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "potatura di formazione a 5cm dal suolo", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Primulaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 50, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 3, "rinvaso_ogni_mesi": 18, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$ardisia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Begonia$t$, $t$Begonia$t$, $t$Begoniaceae$t$, $t$Genere di circa 1000 specie originarie delle regioni tropicali e subtropicali di Africa, America, Asia e delle regioni andine e himalaiane. Le tante varietà coltivate sono per lo più ibridi classificati per tipo di fiore (semplice, semi-doppio, doppio); portamento eretto o ricadente.$t$, $j${"luce": "Mezz'ombra o ombra leggera: posizione luminosa ma senza raggi diretti del sole", "acqua": "Regolare con acqua non calcarea e tiepida, terreno mai secco né troppo bagnato", "terreno": "Leggero, poroso, ricco di humus: terriccio per vasi, ghiaia, torba e concime organico"}$j$::jsonb, ARRAY[$t$non nebulizzare foglie e fiori: l'umidità sulle superfici attira le muffe$t$, $t$se la pianta appassisce → probabilmente non ha abbastanza luce$t$, $t$se le foglie si sciupano/si macchiano → ambiente troppo caldo$t$, $t$se i fiori cadono precocemente → aria troppo secca$t$, $t$molte varietà ibride (soprattutto gli Elatior) fioriscono e poi muoiono, spesso non sopravvivono oltre una stagione$t$, $t$rinvasare in aprile; concimare con fertilizzante a bassa concentrazione di calcio$t$], $j${"irrigazione": {"primavera": "regolare, con acqua tiepida non calcarea", "estate": "regolare", "autunno": "ridotta", "inverno": "diradata, pianta a riposo"}, "concimazione": {"primavera": "con fertilizzante a bassa concentrazione di calcio", "estate": "idem", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Begoniaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 25, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 2, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.9}$j$::jsonb, $t$annuale$t$, $t$begonia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Beloperone$t$, $t$Beloperone guttata$t$, $t$Acanthaceae$t$, $t$Genere nativo del Messico, con circa 60 specie semiarbustive tropicali. B. guttata (nota anche come Justicia brandegeana, "pianta gamberetto") ha fusti pelosi verdi, foglie tomentose ovali verde acceso e spighe fiorali pendule rosso-brunastre o rosa-salmone, con piccoli fiori bianchi che spuntano dal labbro inferiore.$t$, $j${"luce": "Pieno sole", "acqua": "Regolare, terreno mai secco del tutto", "terreno": "Universale, con aggiunta di torba e sabbia"}$j$::jsonb, ARRAY[$t$se il terreno si secca completamente le foglie cadono e i rami colpiti non ricrescono$t$, $t$potare a due terzi dal suolo in primavera, per rinnovare la pianta e favorire una nuova fioritura$t$, $t$cimare i germogli in estate per una forma più compatta$t$, $t$recidere i fiori appassiti$t$, $t$temperatura 16-22°C, in inverno 12-16°C$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare, mai secco", "autunno": "moderata", "inverno": "regolare, a bassa temperatura"}, "concimazione": {"primavera": "settimanale", "estate": "settimanale", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "potatura energica a due terzi dal suolo", "estate": "cimare i germogli", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Acanthaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["primavera"], "finestra_trapianto": ["primavera", "estate"], "resistenza_gelo": "nessuna", "spaziatura_cm": 45, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 3, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$beloperone$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$);
